import csv
import glob
import os
from datetime import date, timedelta

TODAY = date(2025, 8, 12)
LAST_7_START = TODAY - timedelta(days=6)
LAST_30_START = TODAY - timedelta(days=29)
MONTH_START = TODAY.replace(day=1)

SEVERITIES = ["ERROR", "WARNING", "INFO"]

counts = {
    "today": {s: 0 for s in SEVERITIES},
    "last_7_days": {s: 0 for s in SEVERITIES},
    "last_30_days": {s: 0 for s in SEVERITIES},
    "month_to_date": {s: 0 for s in SEVERITIES},
    "total": {s: 0 for s in SEVERITIES},
}

fname_re = re.compile(r"^(\d{4}-\d{2}-\d{2})_.*\.log$")
sev_re = re.compile(r"\[(ERROR|WARNING|INFO)\]")

for path in glob.glob("/app/logs/*.log"):
    fname = os.path.basename(path)
    m = fname_re.match(fname)
    if not m:
        continue
    file_date = date.fromisoformat(m.group(1))

    with open(path, "r", errors="replace") as f:
        file_counts = {s: 0 for s in SEVERITIES}
        for line in f:
            sm = sev_re.search(line)
            if sm:
                file_counts[sm.group(1)] += 1

    for s in SEVERITIES:
        c = file_counts[s]
        if c == 0:
            continue
        counts["total"][s] += c
        if file_date == TODAY:
            counts["today"][s] += c
        if LAST_7_START <= file_date <= TODAY:
            counts["last_7_days"][s] += c
        if LAST_30_START <= file_date <= TODAY:
            counts["last_30_days"][s] += c
        if MONTH_START <= file_date <= TODAY:
            counts["month_to_date"][s] += c

with open("/app/summary.csv", "w", newline="") as f:
    writer = csv.writer(f)
    writer.writerow(["period", "severity", "count"])
    for period in ["today", "last_7_days", "last_30_days", "month_to_date", "total"]:
        for sev in SEVERITIES:
            writer.writerow([period, sev, counts[period][sev]])

print("done")
